t.script:
document.addEventListener("DOMContentLoaded", function () {

    const home =
        document.getElementById("isekai-home");

    if (!home) {
        return;
    }


    /* =================================================
       MENÚ DE CATEGORÍAS
       ================================================= */

    const categoryDropdowns =
        home.querySelectorAll(
            ".isekai-category-dropdown"
        );


    categoryDropdowns.forEach(function (dropdown) {

        const button =
            dropdown.querySelector(
                ".isekai-category-button"
            );

        const menu =
            dropdown.querySelector(
                ".isekai-subcategory-menu"
            );


        /* Solo las categorías que tienen
           subcategorías tienen desplegable */

        if (!button || !menu) {
            return;
        }


        button.addEventListener(
            "click",
            function (event) {

                /*
                 * Si la categoría tiene subcategorías,
                 * el primer click abre el menú.
                 *
                 * Evitamos que el enlace navegue
                 * mientras se abre.
                 */

                event.preventDefault();

                event.stopPropagation();


                const isOpen =
                    dropdown.classList.contains(
                        "isekai-open"
                    );


                /* Cerramos las demás categorías */

                categoryDropdowns.forEach(
                    function (otherDropdown) {

                        otherDropdown.classList.remove(
                            "isekai-open"
                        );

                    }
                );


                /* Si estaba cerrada, la abrimos */

                if (!isOpen) {

                    dropdown.classList.add(
                        "isekai-open"
                    );

                }

            }
        );


        /* Evitamos que un click dentro del menú
           cierre inmediatamente el desplegable */

        menu.addEventListener(
            "click",
            function (event) {

                event.stopPropagation();

            }
        );

    });


    /* =================================================
       MENÚ DE USUARIO
       ================================================= */

    const userDropdowns =
        home.querySelectorAll(
            ".isekai-user-dropdown"
        );


    userDropdowns.forEach(function (dropdown) {

        const button =
            dropdown.querySelector(
                ".isekai-user-button"
            );

        const menu =
            dropdown.querySelector(
                ".isekai-user-menu"
            );


        if (!button || !menu) {
            return;
        }


        /* =============================================
           CLICK EN EL BOTÓN DE USUARIO
           ============================================= */

        button.addEventListener(
            "click",
            function (event) {

                event.preventDefault();

                event.stopPropagation();


                const isOpen =
                    dropdown.classList.contains(
                        "isekai-open"
                    );


                /* Cerramos otros menús de usuario */

                userDropdowns.forEach(
                    function (otherDropdown) {

                        otherDropdown.classList.remove(
                            "isekai-open"
                        );

                        const otherButton =
                            otherDropdown.querySelector(
                                ".isekai-user-button"
                            );

                        if (otherButton) {

                            otherButton.setAttribute(
                                "aria-expanded",
                                "false"
                            );

                        }

                    }
                );


                /* Abrimos si estaba cerrado */

                if (!isOpen) {

                    dropdown.classList.add(
                        "isekai-open"
                    );

                    button.setAttribute(
                        "aria-expanded",
                        "true"
                    );

                }

            }
        );


        /* =============================================
           CLICK DENTRO DEL MENÚ
           ============================================= */

        menu.addEventListener(
            "click",
            function (event) {

                event.stopPropagation();

            }
        );

    });


    /* =================================================
       CLICK FUERA DE LOS MENÚS
       ================================================= */

    document.addEventListener(
        "click",
        function () {


            /* Cerrar categorías */

            categoryDropdowns.forEach(
                function (dropdown) {

                    dropdown.classList.remove(
                        "isekai-open"
                    );

                }
            );


            /* Cerrar usuario */

            userDropdowns.forEach(
                function (dropdown) {

                    dropdown.classList.remove(
                        "isekai-open"
                    );


                    const button =
                        dropdown.querySelector(
                            ".isekai-user-button"
                        );


                    if (button) {

                        button.setAttribute(
                            "aria-expanded",
                            "false"
                        );

                    }

                }
            );

        }
    );

});
